import java.io.*;
import java.util.*;
import java.util.jar.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;

// Parses classfiles as data through trusted ASM. Never loads inspected classes.
public class BytecodeDump {
 static String str(Object o) { if(o==null)return "null"; if(o instanceof Type)return "Type:"+((Type)o).getDescriptor(); if(o instanceof Handle){Handle h=(Handle)o;return "Handle:"+h.getTag()+":"+h.getOwner()+":"+h.getName()+":"+h.getDesc()+":"+h.isInterface();} if(o instanceof Float)return "Float:"+Integer.toHexString(Float.floatToRawIntBits((Float)o));if(o instanceof Double)return "Double:"+Long.toHexString(Double.doubleToRawLongBits((Double)o)); return o.getClass().getSimpleName()+":"+o; }
 static String q(String s){ StringBuilder b=new StringBuilder("\""); for(char c:s.toCharArray()){if(c=='"'||c=='\\')b.append('\\').append(c);else if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}return b.append('"').toString(); }
 static String json(Object o){if(o==null)return "null";if(o instanceof Map){List<String>a=new ArrayList<>();for(Object k:((Map<?,?>)o).keySet())a.add(q(k.toString())+":"+json(((Map<?,?>)o).get(k)));return "{"+String.join(",",a)+"}";}if(o instanceof Iterable){List<String>a=new ArrayList<>();for(Object v:(Iterable<?>)o)a.add(json(v));return "["+String.join(",",a)+"]";}if(o instanceof Number||o instanceof Boolean)return o.toString();return q(o.toString());}
 static Map<String,Object> map(Object... xs){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<xs.length;i+=2)m.put(xs[i].toString(),xs[i+1]);return m;}
 static List<Object> annotations(List<? extends AnnotationNode> ns){List<Object>r=new ArrayList<>();if(ns!=null)for(AnnotationNode n:ns){List<Object>v=new ArrayList<>();if(n.values!=null)for(Object x:n.values)v.add(str(x));r.add(map("type",n.desc,"values",v));}return r;}
 public static void main(String[] args)throws Exception{
  Map<String,Object>out=new TreeMap<>();try(JarFile jar=new JarFile(args[0])){Enumeration<JarEntry>es=jar.entries();while(es.hasMoreElements()){JarEntry e=es.nextElement();if(!e.getName().endsWith(".class"))continue;ClassNode c=new ClassNode();try(InputStream in=jar.getInputStream(e)){new ClassReader(in).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);}
  List<Object>fs=new ArrayList<>();for(FieldNode f:c.fields)fs.add(map("name",f.name,"desc",f.desc,"access",f.access,"value",str(f.value),"signature",f.signature,"annotations",annotations(f.visibleAnnotations),"invisibleAnnotations",annotations(f.invisibleAnnotations)));
  Map<String,Object>ms=new TreeMap<>();for(MethodNode m:c.methods){Map<LabelNode,Integer>labels=new IdentityHashMap<>();int idx=0;for(AbstractInsnNode n:m.instructions){if(n instanceof LabelNode)labels.put((LabelNode)n,idx);if(n.getOpcode()>=0)idx++;}
   List<Object>ins=new ArrayList<>();for(AbstractInsnNode n:m.instructions){int op=n.getOpcode();if(op<0)continue;List<Object>t=new ArrayList<>();t.add(op);
   if(n instanceof IntInsnNode)t.add(((IntInsnNode)n).operand);else if(n instanceof VarInsnNode)t.add(((VarInsnNode)n).var);else if(n instanceof TypeInsnNode)t.add(((TypeInsnNode)n).desc);else if(n instanceof FieldInsnNode){FieldInsnNode x=(FieldInsnNode)n;Collections.addAll(t,x.owner,x.name,x.desc);}else if(n instanceof MethodInsnNode){MethodInsnNode x=(MethodInsnNode)n;Collections.addAll(t,x.owner,x.name,x.desc,x.itf);}else if(n instanceof InvokeDynamicInsnNode){InvokeDynamicInsnNode x=(InvokeDynamicInsnNode)n;Collections.addAll(t,x.name,x.desc,str(x.bsm));for(Object a:x.bsmArgs)t.add(str(a));}else if(n instanceof JumpInsnNode)t.add(labels.get(((JumpInsnNode)n).label));else if(n instanceof LdcInsnNode)t.add(str(((LdcInsnNode)n).cst));else if(n instanceof IincInsnNode){IincInsnNode x=(IincInsnNode)n;Collections.addAll(t,x.var,x.incr);}else if(n instanceof TableSwitchInsnNode){TableSwitchInsnNode x=(TableSwitchInsnNode)n;Collections.addAll(t,x.min,x.max,labels.get(x.dflt));for(LabelNode l:x.labels)t.add(labels.get(l));}else if(n instanceof LookupSwitchInsnNode){LookupSwitchInsnNode x=(LookupSwitchInsnNode)n;t.add(labels.get(x.dflt));t.add(x.keys);for(LabelNode l:x.labels)t.add(labels.get(l));}else if(n instanceof MultiANewArrayInsnNode){MultiANewArrayInsnNode x=(MultiANewArrayInsnNode)n;Collections.addAll(t,x.desc,x.dims);}ins.add(t);}
   List<Object>tc=new ArrayList<>();for(TryCatchBlockNode t:m.tryCatchBlocks)tc.add(Arrays.asList(labels.get(t.start),labels.get(t.end),labels.get(t.handler),t.type));
   ms.put(m.name+m.desc,map("access",m.access,"exceptions",m.exceptions,"signature",m.signature,"annotations",annotations(m.visibleAnnotations),"invisibleAnnotations",annotations(m.invisibleAnnotations),"annotationDefault",str(m.annotationDefault),"code",ins,"handlers",tc));}
  out.put(c.name,map("version",c.version,"access",c.access,"super",c.superName,"interfaces",c.interfaces,"signature",c.signature,"outerClass",c.outerClass,"outerMethod",c.outerMethod,"outerMethodDesc",c.outerMethodDesc,"annotations",annotations(c.visibleAnnotations),"invisibleAnnotations",annotations(c.invisibleAnnotations),"fields",fs,"methods",ms));}}
  try(Writer w=new OutputStreamWriter(new FileOutputStream(args[1]),"UTF-8")){w.write(json(out));}
 }
}
